#!/usr/bin/env python3
"""Exact certificate for a linear monotone NAE-4 equality gadget.

There are no third-party dependencies.  The finite-field construction, all
incidence checks, the exhaustive DPLL search, and the overlap-composition tests
are recomputed from the data below.
"""

from itertools import combinations, product


# Indices, in lexicographic order among the 130 projective lines generated by
# pg_lines(), of a non-2-colourable 99-line core.  Deleting line 0 gives the
# equality gadget.
CORE_INDICES = (
    0, 2, 3, 4, 5, 6, 7, 8, 9, 11, 12, 13, 17, 18, 19, 20, 21, 22,
    24, 26, 27, 28, 30, 31, 33, 34, 35, 37, 38, 39, 40, 41, 43, 44,
    46, 47, 49, 50, 51, 52, 54, 56, 57, 60, 61, 63, 64, 65, 66,
    67, 68, 70, 71, 73, 74, 75, 76, 77, 80, 81, 82, 83, 84, 85,
    88, 91, 92, 93, 94, 95, 96, 97, 98, 99, 100, 101, 102, 103,
    105, 106, 108, 109, 110, 111, 112, 113, 114, 115, 116, 117,
    118, 119, 120, 121, 122, 123, 127, 128, 129,
)


def normalize(vector):
    """Canonical representative of a one-dimensional F_3 subspace."""
    for entry in vector:
        if entry % 3:
            multiplier = 1 if entry % 3 == 1 else 2
            return tuple(multiplier * coordinate % 3 for coordinate in vector)
    raise ValueError("the zero vector has no projective normalization")


def pg_lines():
    """Return the 40 points and 130 lines of PG(3,3), lexicographically."""
    points = sorted(
        {normalize(v) for v in product(range(3), repeat=4) if any(v)}
    )
    point_index = {point: index for index, point in enumerate(points)}
    lines = set()
    for first, second in combinations(points, 2):
        span = {
            point_index[
                normalize(
                    tuple((x + scalar * y) % 3 for x, y in zip(first, second))
                )
            ]
            for scalar in range(3)
        }
        span.add(point_index[second])
        lines.add(tuple(sorted(span)))
    return points, sorted(lines)


def is_nae(values):
    return len(set(values)) >= 2


def validate_colouring(clauses, assignment):
    return all(is_nae(tuple(assignment[v] for v in clause)) for clause in clauses)


def exact_dpll(clauses, initial_assignment):
    """Complete two-way DPLL for monotone NAE clauses, with exact propagation.

    A clause containing both colours is satisfied.  If its assigned vertices
    have one colour and exactly one vertex is unassigned, that vertex is forced
    to the other colour.  Otherwise an unresolved variable is branched both
    ways.  Thus every omitted branch is justified by a forced assignment.
    """
    stats = {"nodes": 0, "conflicts": 0, "propagations": 0}

    def search(assignment):
        stats["nodes"] += 1
        while True:
            changed = False
            for clause in clauses:
                values = tuple(assignment[v] for v in clause)
                known = {value for value in values if value >= 0}
                if len(known) >= 2:
                    continue
                unknown = [v for v in clause if assignment[v] < 0]
                if not unknown:
                    stats["conflicts"] += 1
                    return None
                if len(known) == 1 and len(unknown) == 1:
                    assignment[unknown[0]] = 1 - next(iter(known))
                    stats["propagations"] += 1
                    changed = True
            if not changed:
                break

        unresolved = []
        for clause in clauses:
            known = {assignment[v] for v in clause if assignment[v] >= 0}
            if len(known) < 2:
                unresolved.append(clause)
        if not unresolved:
            return assignment

        scores = {}
        for clause in unresolved:
            for vertex in clause:
                if assignment[vertex] < 0:
                    scores[vertex] = scores.get(vertex, 0) + 1
        branch_vertex = max(scores, key=lambda vertex: (scores[vertex], -vertex))
        for value in (0, 1):
            child = assignment[:]
            child[branch_vertex] = value
            result = search(child)
            if result is not None:
                return result
        return None

    solution = search(initial_assignment[:])
    if solution is not None:
        # Variables irrelevant after every clause is already bichromatic may
        # retain -1.  Either value preserves every already-satisfied clause.
        solution = [0 if value < 0 else value for value in solution]
        assert validate_colouring(clauses, solution)
    return solution, stats


def check_linear(clauses):
    maximum = 0
    for first, second in combinations(clauses, 2):
        overlap = len(set(first) & set(second))
        maximum = max(maximum, overlap)
        assert overlap <= 1, (first, second, overlap)
    return maximum


def instantiate_two_clause_overlap(gadget, zero_witness, overlap):
    """Build and check the transformed two-clause instance with overlap 2--4."""
    assert overlap in (2, 3, 4)
    first = tuple(range(4))
    second = tuple(range(overlap)) + tuple(range(4, 8 - overlap))
    original_clauses = (first, second)

    transformed = []
    occurrence_variables = {}
    gadget_maps = []
    for clause_index, clause in enumerate(original_clauses):
        new_clause = []
        for position, original_vertex in enumerate(clause):
            tag = (clause_index, position)
            mapping = {0: ("original", original_vertex)}
            for point in range(1, 40):
                mapping[point] = ("gadget", tag, point)
            occurrence_variables[tag] = mapping[1]
            gadget_maps.append((original_vertex, mapping))
            transformed.extend(tuple(mapping[p] for p in edge) for edge in gadget)
            new_clause.append(mapping[1])
        transformed.append(tuple(new_clause))

    maximum_overlap = check_linear(transformed)
    variables = set().union(*(set(clause) for clause in transformed))

    rows = 0
    canonical_matches = True
    original_vertices = sorted(set(first) | set(second))
    for values in product((0, 1), repeat=len(original_vertices)):
        original_assignment = dict(zip(original_vertices, values))
        original_satisfied = all(
            is_nae(tuple(original_assignment[v] for v in clause))
            for clause in original_clauses
        )
        transformed_assignment = {
            ("original", v): value for v, value in original_assignment.items()
        }
        for original_vertex, mapping in gadget_maps:
            colour = original_assignment[original_vertex]
            witness = zero_witness if colour == 0 else [1 - x for x in zero_witness]
            for point in range(1, 40):
                transformed_assignment[mapping[point]] = witness[point]
        transformed_satisfied = all(
            is_nae(tuple(transformed_assignment[v] for v in clause))
            for clause in transformed
        )
        canonical_matches &= original_satisfied == transformed_satisfied
        rows += 1

    assert canonical_matches
    return {
        "overlap": overlap,
        "variables": len(variables),
        "clauses": len(transformed),
        "maximum_pairwise_clause_intersection": maximum_overlap,
        "original_truth_table_rows": rows,
        "canonical_extension_matches_original": canonical_matches,
    }


def main():
    points, all_lines = pg_lines()
    assert len(points) == 40
    assert len(all_lines) == 130
    assert all(len(line) == 4 for line in all_lines)
    assert check_linear(all_lines) == 1

    core = [all_lines[index] for index in CORE_INDICES]
    deleted_line = all_lines[0]
    assert deleted_line == (0, 1, 2, 3)
    assert core[0] == deleted_line
    gadget = core[1:]
    assert len(core) == 99
    assert len(gadget) == 98
    assert check_linear(gadget) == 1

    core_solution, core_stats = exact_dpll(core, [-1] * 40)
    assert core_solution is None

    initial = [-1] * 40
    for terminal in deleted_line:
        initial[terminal] = 0
    zero_witness, gadget_stats = exact_dpll(gadget, initial)
    assert zero_witness is not None
    assert tuple(zero_witness[v] for v in deleted_line) == (0, 0, 0, 0)
    one_witness = [1 - value for value in zero_witness]
    assert validate_colouring(gadget, one_witness)

    # Exact terminal projection.  The two monochromatic rows have the witnesses
    # above.  In every other row, the deleted line is NAE; a gadget extension
    # would therefore colour all 99 core lines, contradicting exhaustive UNSAT.
    terminal_projection = {}
    for pattern in product((0, 1), repeat=4):
        terminal_projection["".join(map(str, pattern))] = (
            "SAT" if len(set(pattern)) == 1 else "UNSAT"
        )

    compositions = [
        instantiate_two_clause_overlap(gadget, zero_witness, overlap)
        for overlap in (2, 3, 4)
    ]

    print("points=40 projective_lines=130 core_lines=99 gadget_clauses=98")
    print("deleted_line=" + repr(deleted_line))
    print("full_core=UNSAT exhaustive_dpll=" + repr(core_stats))
    print("zero_terminal_witness=" + "".join(map(str, zero_witness)))
    print("zero_witness_search=" + repr(gadget_stats))
    print("terminal_projection=" + repr(terminal_projection))
    for composition in compositions:
        print("composition=" + repr(composition))
    print("CERTIFICATE_OK")


if __name__ == "__main__":
    main()
